/**
 * Smoke-test stub for the host SSRF guard. Real behaviour (private/loopback
 * blocking, DNS pinning) is the host's job; here we only need HTTP fetching to
 * work so the inbound-by-URL path can be exercised.
 */
export async function fetchWithSsrFGuard(params) {
  const response = await fetch(params.url, {
    method: params.init?.method ?? "GET",
    redirect: "follow",
  });
  return {
    response,
    finalUrl: params.url,
    release: async () => {},
  };
}

export function formatErrorMessage(error) {
  return error instanceof Error ? error.message : String(error);
}
